 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    # Join matching non-background markers across an unobstructed run of background.
    for r in range(h):
        markers = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(markers, markers[1:]):
            if grid[r][a] == grid[r][b] and all(grid[r][c] == background for c in range(a+1, b)):
                for c in range(a+1, b):
                    out[r][c] = 3
    for c in range(w):
        markers = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(markers, markers[1:]):
            if grid[a][c] == grid[b][c] and all(grid[r][c] == background for r in range(a+1, b)):
                for r in range(a+1, b):
                    out[r][c] = 3
    return out
